#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);OUT=${OUT:-$ROOT/work/results/l5_block32_tile16_candidate_e1};R=$ROOT/scripts/run_memory_capped.sh;V=${VERILATOR:-$ROOT/work/toolchain/conda/bin/verilator};PY=${PYTHON:-python3};mkdir -p "$OUT/vectors";PYTHONPATH="$ROOT/src" taskset -c 8-23 "$PY" "$ROOT/scripts/generate_block32_tile16_vectors.py" --out "$OUT/vectors" --cases 16 >"$OUT/vector_generation.log";"$ROOT/scripts/generate_all_hardfloat_primitives.sh"
run(){ local limit=$1;shift;MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" timeout --foreground --signal=INT --kill-after=30s "$limit" "$@";}
S=("$ROOT/work/generated/l5_all_primitives/HeteroAllPrimitives.sv" "$ROOT/rtl/common/rv_fifo.sv" "$ROOT/rtl/attention/fp32_exp2_pwl_i1_candidate.sv" "$ROOT/rtl/attention/fp32_block32_softmax_tile_math_lane.sv" "$ROOT/rtl/attention/fp32_block32_softmax_row_bank.sv" "$ROOT/rtl/attention/fp32_block32_softmax_tile_store.sv" "$ROOT/rtl/attention/fp32_block32_softmax_tile16_candidate.sv" "$ROOT/tb/tb_fp32_block32_softmax_tile16_candidate.sv")
run 600s "$V" --binary --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL -Wno-WIDTH -Wno-PINCONNECTEMPTY -Wno-PINMISSING -Wno-SYNCASYNCNET -j 8 -MAKEFLAGS "AR=/usr/bin/ar CXX=/usr/bin/g++" --top-module tb_fp32_block32_softmax_tile16_candidate --Mdir "$OUT/obj" -o tb "${S[@]}" >"$OUT/build.log" 2>&1
run 600s "$OUT/obj/tb" +VECTORS="$OUT/vectors"|tee "$OUT/tb.log";grep -q 'BLOCK32_TILE16_CANDIDATE_PASS cases=16 rows_per_case=16 scores_per_case=512' "$OUT/tb.log";run 600s "$OUT/obj/tb" +VECTORS="$OUT/vectors" +NOSTALL|tee "$OUT/tb_nominal.log";grep -q 'nominal=1' "$OUT/tb_nominal.log"
